// One Promotion step: the roster unit `id` at `rank` (1 Basic, 2 Advanced, 3 Elite)
// promotes after `required_xp` to `target` at `target_rank`. A null target is the same
// unit at the next rank (0 A.D.'s _b -> _a -> _e templates); otherwise the unit becomes
// that roster unit (Promotion.js ChangeEntityTemplate).
struct PromotionStep {
	const char *id;
	uint8_t rank;
	uint16_t required_xp;
	const char *target;
	uint8_t target_rank;
};

