// What one rank adds: unit_advanced.json (Advanced and Elite units) and unit_elite.json
// (Elite units). An Elite unit has both. Melee: Attack/Melee damage and resistance;
// healers: Heal/Health and Heal/Range; gather is ResourceGatherer/BaseSpeed; train time is
// Cost/BuildTime of a unit trained at that rank.
struct RankBonus {
	float health_mul;
	float melee_damage_mul;
	float melee_armor_add;
	float capture_add;
	float heal_add;
	float heal_range_add;
	float gather_mul;
	float train_time_mul;
};

inline constexpr RankBonus RANK_BONUS_ADVANCED = {1.25f, 1.1f, 0.0f, 0.7f, 5.0f, 3.0f, 0.7f, 1.2f};
inline constexpr RankBonus RANK_BONUS_ELITE = {1.25f, 1.1f, 0.0f, 0.8f, 5.0f, 3.0f, 0.7f, 1.2f};

// Technologies that change Promotion/RequiredXp for units with every `need` class and
// no `forbid` class (TechClass bits), at `rank` (0 any): multiply, or replace with 0.
// TECH_NONE rows are auto-researched: every player has them.
struct PromotionXpTech {
	uint8_t tech;
	float multiply;
	bool replace_zero;
	TechClasses need;
	TechClasses forbid;
	uint8_t rank;
};

